import logging
from typing import List, Union

import torch
import triton
import triton.language as tl

logger = logging.getLogger(__name__)


@triton.jit
def dsplit_copy_kernel(
    input_ptr,
    output_ptr,
    num_elements,
    dim_size_input: tl.constexpr,  # depth (dim=2) size of the input
    dim_size_output: tl.constexpr,  # depth size of this chunk
    start: tl.constexpr,  # chunk start offset along dim=2
    prod_post: tl.constexpr,  # product of dims after dim=2
    BLOCK_SIZE: tl.constexpr,
):
    """Copy one depth-wise chunk from ``input`` into a contiguous ``output``.

    The input is viewed as (pre, dim_size_input, prod_post). This chunk owns
    ``input[:, :, start:start + dim_size_output, ...]``; each output element is
    mapped back to its source, adding ``start`` to the depth index (the offset
    that the shared helper must account for).
    """
    pid = tl.program_id(0)
    offsets = pid * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < num_elements

    # Decompose the contiguous output index into (pre, depth, post).
    pre_idx = offsets // (dim_size_output * prod_post)
    depth_idx = (offsets // prod_post) % dim_size_output
    post_idx = offsets % prod_post

    # Map back to the input, offsetting the depth by this chunk's start.
    input_idx = (
        pre_idx * dim_size_input * prod_post
        + (depth_idx + start) * prod_post
        + post_idx
    )

    data = tl.load(input_ptr + input_idx, mask=mask)
    tl.store(output_ptr + offsets, data, mask=mask)


def dsplit(input: torch.Tensor, indices_or_sections: Union[int, List[int]]):
    """Split a tensor along the third axis (depth-wise).

    ``torch.dsplit`` is ``torch.tensor_split`` along ``dim=2`` and requires a
    tensor with three or more dimensions. Each chunk is produced by a Triton
    kernel that copies the corresponding depth slice into a freshly allocated
    output, so no PyTorch computation operator is called (only ``torch.empty``
    for allocation, per the host-function conventions).
    """
    logger.debug("GEMS DSPLIT")

    if input.ndim < 3:
        raise RuntimeError(
            f"dsplit requires a tensor with 3 or more dimensions, got {input.ndim}"
        )

    dim = 2
    dim_size = input.shape[dim]

    # Resolve the chunk sizes along the depth dimension.
    if isinstance(indices_or_sections, int):
        n = indices_or_sections
        if n <= 0:
            raise ValueError(f"indices_or_sections must be positive, got {n}")
        # torch.tensor_split semantics: the first `remainder` chunks get one
        # extra element when the dimension does not divide evenly.
        base = dim_size // n
        remainder = dim_size % n
        chunk_sizes = [base + 1 if i < remainder else base for i in range(n)]
    else:
        chunk_sizes = []
        prev = 0
        for idx in indices_or_sections:
            idx = max(0, min(idx, dim_size))
            chunk_sizes.append(idx - prev)
            prev = idx
        chunk_sizes.append(dim_size - prev)

    # prod of dims before / after the depth dimension.
    prod_post = 1
    for s in input.shape[dim + 1 :]:
        prod_post *= s
    prod_pre = 1
    for s in input.shape[:dim]:
        prod_pre *= s

    input_contiguous = input.contiguous()

    # BLOCK_SIZE=1024: standard 1D copy tile, memory-bound so any power-of-two
    # in the 256-2048 range performs equivalently.
    BLOCK_SIZE = 1024

    outputs = []
    start = 0
    for chunk_size in chunk_sizes:
        out_shape = list(input.shape)
        out_shape[dim] = chunk_size
        output = torch.empty(out_shape, dtype=input.dtype, device=input.device)

        num_elements = prod_pre * chunk_size * prod_post
        if num_elements > 0:
            grid = (triton.cdiv(num_elements, BLOCK_SIZE),)
            dsplit_copy_kernel[grid](
                input_contiguous,
                output,
                num_elements,
                dim_size,
                chunk_size,
                start,
                prod_post,
                BLOCK_SIZE=BLOCK_SIZE,
            )
        outputs.append(output)
        start += chunk_size

    return tuple(outputs)
